{
  "technical_and_design_decisions": [
    "Migrate wiki content into the main repository in AsciiDoc/Markdown format under the /docs directory to enable versioning alongside code releases.",
    "Integrate Hadoop namenode configuration defaults into Spring XD DSL shell configuration files (e.g., xd-shell.cfg/application.yml) so DSL sessions pick them up automatically.",
    "Implement a passthrough step configuration option for JDBC-to-HDFS batch jobs that bypasses chunking and item reader/writer wrappers for raw stream transfer.",
    "Refactor Spring XD's batch integration layer to consume the upgraded Spring Batch dependency featuring decoupled execution context lifecycle, deprecating the workaround from XD-2486.",
    "Extend the Spring XD module deployment registry and bean scanner to properly detect and register custom batch jobs configured via Java @Configuration classes.",
    "Design an abstract Runtime Container SPI and implement Receptor API as a concrete implementation, allowing execution target pluggability across Lattice, Diego, and other orchestrators.",
    "Use Spring Hadoop/FileSystem API inside the Shell Processor to fetch and cache Python scripts directly from HDFS before invoking the Python runtime in Cloud Foundry."
  ],
  "assumptions": [
    "Development and testing environments (including Hadoop HDFS, Cloud Foundry/Diego test instances, and Java 17 toolchains) are available.",
    "The required Spring Batch release containing the execution context decoupling fix is published or accessible via repository dependencies.",
    "The scope covers end-to-end implementation, unit testing, integration testing, and documentation by a single software developer.",
    "Existing XML-based modules will remain supported alongside the new Java Config custom job module capabilities."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Wiki Content Migration to Project Repository",
      "activity_description": "Export existing wiki pages, convert formatting to Markdown/AsciiDoc, organize within repository docs folder, fix relative links, and verify versioning.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Hadoop Namenode DSL Auto-Configuration",
      "activity_description": "Update DSL shell config parser and initialization logic to store and auto-apply default Hadoop namenode parameters across sessions.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "JDBC-to-HDFS Passthrough Batch Job Implementation",
      "activity_description": "Implement passthrough execution path for jdbchdfs batch job templates to eliminate chunk processing overhead; add unit and performance test cases.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Spring Batch Decoupling & XD-2486 Workaround Refactoring",
      "activity_description": "Upgrade Spring Batch dependency, refactor XD job launch lifecycle integration to remove XD-2486 workaround, and verify classloader and serialization behavior.",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Java Config Custom Job Module Support & Bug Fix",
      "activity_description": "Investigate and fix module deployment issue for Java Config job modules, update module registry scanner, and write integration tests deploying custom JAR modules.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Pluggable Container SPI & Receptor API Implementation",
      "activity_description": "Design generic Runtime SPI for XD execution targets, implement the Receptor API provider for Diego/Lattice, and write contract tests.",
      "most_likely_effort": 6.0
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Module Metadata & shortDescription Documentation Updates",
      "activity_description": "Audit existing module definitions, add shortDescription fields across all module descriptors and documentation files, and verify metadata output.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "HDFS Python Script Fetching in Shell Processor",
      "activity_description": "Enhance XD Shell Processor to resolve and download Python script files from HDFS paths and execute them in Cloud Foundry Python runtimes.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Integration Testing and Increment Validation",
      "activity_description": "Perform full regression testing, cross-feature integration tests, build configuration validation, and prepare release documentation.",
      "most_likely_effort": 3.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 30.0
  }
}
